const r = $input.first().json;
const cols = r.data.cols.map(c => c.name);
const rows = r.data.rows;
const ingested_at = new Date().toISOString();
return rows.map(row => ({
  json: { ...Object.fromEntries(cols.map((c, i) => [c, row[i]])), ingested_at }
}));

const items = $input.all();
if (!items.length) return [{ json: { query: 'SELECT 1' } }];
const TABLE = 'contractors', CONFLICT = 'id', CHUNK = 500;
const cols = Object.keys(items[0].json);
const nonPK = cols.filter(c => c !== CONFLICT);
const colList = cols.map(c => '"' + c + '"').join(', ');
const updSet = nonPK.map(c => '"' + c + '" = EXCLUDED."' + c + '"').join(', ');
const Q = "'";
const esc = v => v == null ? 'NULL' : typeof v === 'boolean' ? (v ? 'TRUE' : 'FALSE') : typeof v === 'number' ? String(v) : Q + String(v).replace(/'/g, Q+Q) + Q;
const out = [];
for (let i = 0; i < items.length; i += CHUNK) {
  const vals = items.slice(i, i+CHUNK).map(it => '(' + cols.map(c => esc(it.json[c])).join(',') + ')').join(',');
  out.push({ json: { query: 'INSERT INTO ' + TABLE + ' (' + colList + ') VALUES ' + vals + ' ON CONFLICT (' + CONFLICT + ') DO UPDATE SET ' + updSet } });
}
return out;

